from collections import defaultdict, OrderedDict

class LFUCache:
    def __init__(self, capacity: int) -> None:
        self.cap = capacity
        self.min_freq = 0
        self.key_map: dict[int, list] = {}           # key -> [val, freq]
        self.freq_map: dict[int, OrderedDict] = defaultdict(OrderedDict)

    def _increment(self, key: int) -> None:
        val, freq = self.key_map[key]
        del self.freq_map[freq][key]
        if not self.freq_map[freq] and freq == self.min_freq:
            self.min_freq += 1
        self.key_map[key] = [val, freq + 1]
        self.freq_map[freq + 1][key] = None

    def get(self, key: int) -> int:
        if key not in self.key_map:
            return -1
        self._increment(key)
        return self.key_map[key][0]

    def put(self, key: int, value: int) -> None:
        if self.cap == 0:
            return
        if key in self.key_map:
            self.key_map[key][0] = value
            self._increment(key)
        else:
            if len(self.key_map) >= self.cap:
                # evict least frequent (and least recent among ties)
                evict, _ = self.freq_map[self.min_freq].popitem(last=False)
                del self.key_map[evict]
            self.key_map[key] = [value, 1]
            self.freq_map[1][key] = None
            self.min_freq = 1

import math
import hashlib

class BloomFilter:
    def __init__(self, n: int, fp_rate: float = 0.01) -> None:
        """n: expected elements; fp_rate: false-positive probability."""
        # Optimal bit array size and hash count
        self.m = math.ceil(-(n * math.log(fp_rate)) / (math.log(2) ** 2))
        self.k = max(1, round((self.m / n) * math.log(2)))
        self.bits = bytearray(math.ceil(self.m / 8))

    def _hashes(self, item: str) -> list[int]:
        # Simulate k hash functions via double hashing
        h1 = int(hashlib.md5(item.encode()).hexdigest(), 16)
        h2 = int(hashlib.sha1(item.encode()).hexdigest(), 16)
        return [(h1 + i * h2) % self.m for i in range(self.k)]

    def add(self, item: str) -> None:
        for idx in self._hashes(item):
            self.bits[idx // 8] |= (1 << (idx % 8))

    def __contains__(self, item: str) -> bool:
        return all(
            (self.bits[idx // 8] >> (idx % 8)) & 1
            for idx in self._hashes(item)
        )

bf = BloomFilter(n=1_000_000, fp_rate=0.01)  # ~1% false positive rate
bf.add("user:42")
print("user:42" in bf)   # True (probably present)
print("user:99" in bf)   # False (definitely absent)

import hashlib

class CountMinSketch:
    def __init__(self, width: int = 1000, depth: int = 5) -> None:
        self.width = width
        self.depth = depth
        self.table = [[0] * width for _ in range(depth)]
        # Use different seeds to simulate independent hash functions
        self.seeds = [i * 2654435761 for i in range(1, depth + 1)]

    def _hashes(self, item: str) -> list[int]:
        h = int(hashlib.sha256(item.encode()).hexdigest(), 16)
        return [(h ^ seed) % self.width for seed in self.seeds]

    def add(self, item: str, count: int = 1) -> None:
        for row, col in enumerate(self._hashes(item)):
            self.table[row][col] += count

    def estimate(self, item: str) -> int:
        return min(
            self.table[row][col]
            for row, col in enumerate(self._hashes(item))
        )

# Estimate URL hit counts in a web log stream
cms = CountMinSketch(width=1000, depth=5)
for url in ["/home"] * 500 + ["/about"] * 100 + ["/home"] * 200:
    cms.add(url)
print(cms.estimate("/home"))   # ~700 (possibly slight overcount)
print(cms.estimate("/about"))  # ~100

import random
from typing import Optional

MAX_LEVEL = 16
P = 0.5

class SkipNode:
    def __init__(self, key: float, level: int) -> None:
        self.key = key
        self.forward: list[Optional['SkipNode']] = [None] * (level + 1)

class SkipList:
    def __init__(self) -> None:
        self.level = 0
        self.header = SkipNode(float('-inf'), MAX_LEVEL)

    def _random_level(self) -> int:
        lvl = 0
        while random.random() < P and lvl < MAX_LEVEL:
            lvl += 1
        return lvl

    def search(self, key: float) -> bool:
        curr = self.header
        for i in range(self.level, -1, -1):
            while curr.forward[i] and curr.forward[i].key < key:
                curr = curr.forward[i]
        curr = curr.forward[0]
        return curr is not None and curr.key == key

    def insert(self, key: float) -> None:
        update = [self.header] * (MAX_LEVEL + 1)
        curr = self.header
        for i in range(self.level, -1, -1):
            while curr.forward[i] and curr.forward[i].key < key:
                curr = curr.forward[i]
            update[i] = curr
        new_level = self._random_level()
        if new_level > self.level:
            for i in range(self.level + 1, new_level + 1):
                update[i] = self.header
            self.level = new_level
        node = SkipNode(key, new_level)
        for i in range(new_level + 1):
            node.forward[i] = update[i].forward[i]
            update[i].forward[i] = node

