import hashlib

M = 8   # 2^8 = 256 node ring

def chord_id(key: str) -> int:
    return int(hashlib.sha1(key.encode()).hexdigest(), 16) % (2 ** M)

class ChordNode:
    def __init__(self, ip: str) -> None:
        self.id = chord_id(ip)
        # finger[i] = successor of (self.id + 2^i) mod 2^M
        self.finger: list['ChordNode | None'] = [None] * M
        self.successor: 'ChordNode | None' = None

    def find_successor(self, key_id: int) -> 'ChordNode':
        """Route query toward the node responsible for key_id."""
        if self._between(key_id, self.id, self.successor.id):  # type: ignore
            return self.successor  # type: ignore
        # Forward to closest preceding finger
        closest = self._closest_preceding_finger(key_id)
        return closest.find_successor(key_id)   # recurse (O(log n) hops)

    def _between(self, x: int, a: int, b: int) -> bool:
        """Is x in the half-open range (a, b] on the ring?"""
        if a < b:
            return a < x <= b
        return x > a or x <= b

    def _closest_preceding_finger(self, key_id: int) -> 'ChordNode':
        for i in range(M - 1, -1, -1):
            f = self.finger[i]
            if f and self._between(f.id, self.id, key_id):
                return f
        return self  # type: ignore

import hashlib
from dataclasses import dataclass
from typing import Optional

def sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

@dataclass
class MerkleNode:
    hash: str
    left: Optional['MerkleNode'] = None
    right: Optional['MerkleNode'] = None

def build_merkle_tree(data_blocks: list[bytes]) -> MerkleNode:
    leaves = [MerkleNode(sha256(block)) for block in data_blocks]
    if not leaves:
        return MerkleNode(sha256(b''))

    layer = leaves
    while len(layer) > 1:
        if len(layer) % 2 != 0:    # duplicate last leaf if odd count
            layer.append(layer[-1])
        next_layer: list[MerkleNode] = []
        for i in range(0, len(layer), 2):
            combined = (layer[i].hash + layer[i + 1].hash).encode()
            parent = MerkleNode(
                hash=sha256(combined),
                left=layer[i],
                right=layer[i + 1]
            )
            next_layer.append(parent)
        layer = next_layer

    return layer[0]   # root

blocks = [b"tx1", b"tx2", b"tx3", b"tx4"]
root = build_merkle_tree(blocks)
print(f"Merkle root: {root.hash[:16]}...")

import hashlib
import bisect

class ConsistentHashRing:
    def __init__(self, nodes: list[str] = [], replicas: int = 150) -> None:
        self.replicas = replicas     # virtual nodes per physical node
        self.ring: dict[int, str] = {}
        self.sorted_keys: list[int] = []
        for node in nodes:
            self.add_node(node)

    def _hash(self, key: str) -> int:
        return int(hashlib.md5(key.encode()).hexdigest(), 16)

    def add_node(self, node: str) -> None:
        for i in range(self.replicas):
            virtual_key = self._hash(f"{node}:{i}")
            self.ring[virtual_key] = node
            bisect.insort(self.sorted_keys, virtual_key)

    def remove_node(self, node: str) -> None:
        for i in range(self.replicas):
            virtual_key = self._hash(f"{node}:{i}")
            del self.ring[virtual_key]
            idx = bisect.bisect_left(self.sorted_keys, virtual_key)
            self.sorted_keys.pop(idx)

    def get_node(self, key: str) -> str:
        if not self.ring:
            raise RuntimeError("No nodes in ring")
        h = self._hash(key)
        idx = bisect.bisect(self.sorted_keys, h) % len(self.sorted_keys)
        return self.ring[self.sorted_keys[idx]]

# Example
ring = ConsistentHashRing(["cache-1", "cache-2", "cache-3"])
print(ring.get_node("user:42"))    # deterministically routes to one node
print(ring.get_node("session:99")) # a different or same node

# Adding a node only remaps ~1/N of keys
ring.add_node("cache-4")

from collections import defaultdict
import re

class InvertedIndex:
    def __init__(self) -> None:
        # term -> {doc_id: [positions]}
        self.index: dict[str, dict[int, list[int]]] = defaultdict(
            lambda: defaultdict(list)
        )
        self.docs: dict[int, str] = {}

    def _tokenize(self, text: str) -> list[str]:
        return re.findall(r'[a-z]+', text.lower())

    def add_document(self, doc_id: int, text: str) -> None:
        self.docs[doc_id] = text
        for pos, term in enumerate(self._tokenize(text)):
            self.index[term][doc_id].append(pos)

    def search(self, query: str) -> list[int]:
        """Return doc IDs containing ALL query terms (AND query)."""
        terms = self._tokenize(query)
        if not terms:
            return []
        # Start with docs containing the first term
        result_set = set(self.index.get(terms[0], {}).keys())
        # Intersect with docs containing each subsequent term
        for term in terms[1:]:
            result_set &= set(self.index.get(term, {}).keys())
        return sorted(result_set)

# Build and query
idx = InvertedIndex()
idx.add_document(1, "distributed systems and hash tables")
idx.add_document(2, "hash tables in Python")
idx.add_document(3, "distributed hash tables for caching")

print(idx.search("hash tables"))       # [1, 2, 3] — all contain both terms
print(idx.search("distributed hash"))  # [1, 3] — intersection
print(idx.search("caching"))           # [3]
